function reverseBits(n: number): number {
  let result = 0;

  // Ровно 32 шага: переносим биты n в result в обратном порядке
  for (let i = 0; i < 32; i++) {
    // Сдвигаем result влево, освобождая младший бит,
    // и записываем туда текущий младший бит n
    result = (result << 1) | (n & 1);

    // Убираем обработанный бит из n.
    // >>> (а не >>) слева дописывает нули, даже если n «отрицательное»
    n >>>= 1;
  }

  // Битовые операции в JS дают знаковое 32-битное число:
  // если старший бит стал 1, result < 0. >>> 0 читает те же биты как беззнаковые
  return result >>> 0;
}

// Время: O(32) = O(1)
// Память: O(1)
